export const gotterdammerungAct2Scenes = [{"number":2,"originalHeading":"ZWEITE SZENE","translatedHeading":"Second Scene","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Uferraum. Vor der Halle der Gibichungen: rechts der offene Eingang zur Halle; links das Rheinufer; von diesem ","translatedTitle":"Riverside area. In front of the Gibichungs' hall: to the right, the open entrance to the hall; to the left, th","participants":[],"sourceStartIndex":0,"sourceLineCount":1,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Uferraum. Vor der Halle der Gibichungen: rechts der offene Eingang zur Halle; links das Rheinufer; von diesem aus erhebt sich eine durch verschiedene Bergpfade gespaltene, felsige Anhöhe quer über die Bühne, nach rechts dem Hintergrunde zu aufsteigend. Dort sieht man einen der Fricka errichteten Weihstein, welchem höher hinauf ein grösserer für Wotan, sowie seitwärts ein gleicher dem Donner geweihter entspricht. Es ist Nacht","translation":"Riverside area. In front of the Gibichungs' hall: to the right, the open entrance to the hall; to the left, the Rhine bank; from this rises a rocky hill, split by various mountain paths, across the stage, ascending to the right towards the background. There, one can see a votive stone erected to Fricka, to which a larger one for Wotan corresponds higher up, and to the side, an identical one dedicated to thunder. It is night.","literalText":true,"sourceStartIndex":0,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Schläfst du, Hagen, mein Sohn?","translatedTitle":"Are you asleep, Hagen, my son?","participants":["ALBERICH","HAGEN"],"sourceStartIndex":1,"sourceLineCount":74,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Hagen, Alberich\nHagen, den Speer im Arm, den Schild zur Seite, sitzt schlafend an einen Pfosten der Halle gelehnt. Der Mond wirft plötzlich ein grelles Licht auf ihn und seine nächste Umgebung; man gewahrt Alberich vor Hagen kauernd, die Arme auf dessen Knie gelehnt\nleise","translation":"Hagen, Alberich\nHagen, spear in his arm, shield at his side, sits asleep, leaning against a post of the hall. The moon suddenly casts a bright light on him and his immediate surroundings; Alberich is seen crouching before Hagen, his arms resting on his knees.\nquiet","literalText":true,"sourceStartIndex":0,"sourceLineCount":3},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Schläfst du, Hagen, mein Sohn?\nDu schläfst und hörst mich nicht,\nden Ruh' und Schlaf verriet?","translation":"Are you asleep, Hagen, my son?\nYou are asleep and don't hear me,\nwho betrayed peace and sleep?","literalText":true,"sourceStartIndex":3,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"leise, ohne sich zu rühren, so dass er immerfort zu schlafen scheint, obwohl er die Augen offen hat","translation":"quietly, without moving, so that he always seems to be asleep, even though his eyes are open.","literalText":true,"sourceStartIndex":6,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Ich höre dich, schlimmer Albe:\nwas hast du meinem Schlaf zu sagen?","translation":"I hear you, worse album:\nWhat do you have to say to my sleep?","literalText":true,"sourceStartIndex":7,"sourceLineCount":2},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Gemahnt sei der Macht,\nder du gebietest,\nbist du so mutig,\nwie die Mutter dich mir gebar!","translation":"Let power be reminded,\nwho you command,\nAre you so brave?\nas your mother bore you to me!","literalText":true,"sourceStartIndex":9,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"immer wie zuvor","translation":"always as before","literalText":true,"sourceStartIndex":13,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Gab mir die Mutter Mut,\nnicht mag ich ihr doch danken,\ndass deiner List sie erlag:\nfrühalt, fahl und bleich,\nhass' ich die Frohen, freue mich nie!","translation":"Did my mother give me courage?\nI don't want to thank her, but I do.\nthat she succumbed to your trick:\nprematurely aged, pale and sallow,\nI hate the cheerful ones, I'm never happy!","literalText":true,"sourceStartIndex":14,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"wie zuvor","translation":"as before","literalText":true,"sourceStartIndex":19,"sourceLineCount":1},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Hagen, mein Sohn! Hasse die Frohen!\nMich Lustfreien, Leidbelasteten\nliebst du so, wie du sollst!\nBist du kräftig, kühn und klug:\ndie wir bekämpfen mit nächtigem Krieg,\nschon gibt ihnen Not unser Neid.\nDer einst den Ring mir entriss,\nWotan, der wütende Räuber,\nvom eignen Geschlechte ward er geschlagen:\nan den Wälsung verlor er Macht und Gewalt;\nmit der Götter ganzer Sippe\nin Angst ersieht er sein Ende.\nNicht ihn fürcht' ich mehr:\nfallen muss er mit allen! -\nSchläfst du, Hagen, mein Sohn?","translation":"Hagen, my son! Hate the merry ones!\nMe, pleasure-less, suffering-laden\nYou love the way you should!\nAre you strong, bold, and clever?\nwhich we fight with nightly war,\nEven our need gives them envy.\nThe one who once snatched the ring from me,\nWotan, the furious robber,\nHe was defeated by his own sex:\nHe lost power and authority to the Wälsung;\nwith the gods of the entire clan\nHe fears his end.\nI no longer fear him:\nHe must fall with everyone!\nAre you asleep, Hagen, my son?","literalText":true,"sourceStartIndex":20,"sourceLineCount":15},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"bleibt unverändert wie zuvor","translation":"remains unchanged as before","literalText":true,"sourceStartIndex":35,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Der Ewigen Macht, wer erbte sie?","translation":"Who inherited the Eternal Power?","literalText":true,"sourceStartIndex":36,"sourceLineCount":1},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Ich - und du! Wir erben die Welt.\nTrüg' ich mich nicht in deiner Treu',\nteilst du meinen Gram und Grimm.\nWotans Speer zerspellte der Wälsung,\nder Fafner, den Wurm, im Kampfe gefällt\nund kindisch den Reif sich errang.\nJede Gewalt hat er gewonnen;\nWalhall und Nibelheim neigen sich ihm.","translation":"Me and you! We inherit the world.\nIf I am not mistaken in your loyalty,\nDo you share my grief and anger?\nWotan's spear shattered the Wälsung,\nFafner, the worm, felled in battle\nand childishly won the hoop.\nHe has won every battle;\nValhalla and Nibelheim bow down to him.","literalText":true,"sourceStartIndex":37,"sourceLineCount":8},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"immer heimlich","translation":"always secretly","literalText":true,"sourceStartIndex":45,"sourceLineCount":1},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"An dem furchtlosen Helden\nerlahmt selbst mein Fluch:\ndenn nicht kennt er des Ringes Wert,\nzu nichts nützt er die neidlichste Macht.\nLachend in liebender Brunst,\nbrennt er lebend dahin.\nIhn zu verderben, taugt uns nun einzig!\nSchläfst du, Hagen, mein Sohn?","translation":"To the fearless hero\nEven my curse weakens:\nfor he does not know the ring's value,\nHe can use even the most envious power for nothing.\nLaughing in loving passion,\nHe burns alive.\nOur only goal now is to ruin him!\nAre you asleep, Hagen, my son?","literalText":true,"sourceStartIndex":46,"sourceLineCount":8},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"wie zuvor","translation":"as before","literalText":true,"sourceStartIndex":54,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Zu seinem Verderben dient er mir schon.","translation":"He is already serving me to his downfall.","literalText":true,"sourceStartIndex":55,"sourceLineCount":1},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Den goldnen Ring,\nden Reif gilt's zu erringen!\nEin weises Weib lebt dem Wälsung zulieb':\nriet es ihm je des Rheines Töchtern,\ndie in Wassers Tiefen einst mich betört,\nzurückzugeben den Ring,\nverloren ging' mir das Gold,\nkeine List erlangte es je.\nDrum, ohne Zögern ziel' auf den Reif!\nDich Zaglosen zeugt' ich mir ja,\ndass wider Helden hart du mir hieltest.\nZwar stark nicht genug, den Wurm zu bestehn,\n- was allein dem Wälsung bestimmt -\nzu zähem Hass doch erzog ich Hagen,\nder soll mich nun rächen,\nden Ring gewinnen\ndem Wälsung und Wotan zum Hohn!\nSchwörst du mir's, Hagen, mein Sohn?","translation":"The golden ring,\nThe hoop must be won!\nA wise woman lives for the sake of the Wälsung:\nDid the daughters of the Rhine ever advise him?\nwho once bewitched me in the depths of the water,\nto return the ring\nI lost the gold,\nNo trick ever achieved it.\nTherefore, aim without hesitation at the rim!\nI begot you, you fearless one,\nthat you stood by me against heroes, tough as nails.\nAlthough not strong enough to survive the worm,\n- which alone determines the Wälsung -\nBut I raised Hagen to a tenacious hatred.\nHe shall now avenge me,\nwin the ring\nTo the Wälsung and Wotan in mockery!\nDo you swear to me, Hagen, my son?","literalText":true,"sourceStartIndex":56,"sourceLineCount":18}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Den Ring soll ich haben:","translatedTitle":"I am to have the ring:","participants":["HAGEN","ALBERICH"],"sourceStartIndex":75,"sourceLineCount":12,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Von hier an bedeckt ein immer finsterer werdender Schatten wieder Alberich. Zugleich beginnt das erste Tagesgrauen\nimmer wie zuvor","translation":"From this point on, an ever-darkening shadow once again covers Alberich. At the same time, the first light of day begins to break.\nalways as before","literalText":true,"sourceStartIndex":74,"sourceLineCount":2},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Den Ring soll ich haben:\nharre in Ruh'!","translation":"I am to have the ring:\nWait in peace!","literalText":true,"sourceStartIndex":76,"sourceLineCount":2},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Schwörst du mir's, Hagen, mein Held?","translation":"Do you swear to me, Hagen, my hero?","literalText":true,"sourceStartIndex":78,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Mir selbst schwör' ich's;\nschweige die Sorge!","translation":"I swear it to myself;\nSilence the worry!","literalText":true,"sourceStartIndex":79,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"wie er allmählich immer mehr dem Blicke entschwindet, wird auch seine Stimme immer unvernehmbarer","translation":"As he gradually disappears from view, his voice also becomes increasingly inaudible.","literalText":true,"sourceStartIndex":81,"sourceLineCount":1},{"speaker":"ALBERICH","speakerTranslation":"ALBERICH","original":"Sei treu, Hagen, mein Sohn!\nTrauter Helde! - Sei treu!\nSei treu! - Treu!","translation":"Be faithful, Hagen, my son!\nDear Hero! - Be faithful!\nBe faithful! - Faithful!","literalText":true,"sourceStartIndex":82,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Alberich ist gänzlich verschwunden. Hagen, der unverändert in seiner Stellung verblieben, blickt regungslos und starren Auges nach dem Rheine hin, auf welchem sich die Morgendämmerung ausbreitet","translation":"Alberich has completely vanished. Hagen, who remained unchanged in his position, gazes motionless and fixedly towards the Rhine, upon which dawn is spreading.","literalText":true,"sourceStartIndex":85,"sourceLineCount":1}]}]},{"number":3,"originalHeading":"ZWEITE SZENE","translatedHeading":"Third Scene","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Hoiho, Hagen! Müder Mann!","translatedTitle":"Hoiho, Hagen! Tired man!","participants":["SIEGFRIED","HAGEN","GUTRUNE"],"sourceStartIndex":0,"sourceLineCount":75,"turns":[{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Hoiho, Hagen! Müder Mann!\nSiehst du mich kommen?","translation":"Hoiho, Hagen! Tired man!\nDo you see me coming?","literalText":true,"sourceStartIndex":0,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"gemächlich sich erhebend","translation":"rising slowly","literalText":true,"sourceStartIndex":2,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Hei, Siegfried?\nGeschwinder Helde?\nWo brausest du her?","translation":"Hey, Siegfried?\nSwift hero?\nWhere are you coming from?","literalText":true,"sourceStartIndex":3,"sourceLineCount":3},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Vom Brünnhildenstein!\nDort sog ich den Atem ein,\nmit dem ich dich rief:\nso schnell war meine Fahrt!\nLangsamer folgt mir ein Paar:\nzu Schiff gelangt das her!","translation":"From Brünnhilde's Stone!\nThere I inhaled my breath,\nwith which I called you:\nMy journey was so fast!\nA couple is following me more slowly:\nIt arrives by ship!","literalText":true,"sourceStartIndex":6,"sourceLineCount":6},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"So zwangst du Brünnhild'?","translation":"So you forced Brünnhilde?","literalText":true,"sourceStartIndex":12,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Wacht Gutrune?","translation":"Does Gutrune watch?","literalText":true,"sourceStartIndex":13,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"in die Halle rufend","translation":"shouting into the hall","literalText":true,"sourceStartIndex":14,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Hoiho, Gutrune! Komm' heraus!\nSiegfried ist da:\nwas säumst du drin?","translation":"Hoiho, Gutrune! Come out!\nSiegfried is here:\nWhat are you hemming inside?","literalText":true,"sourceStartIndex":15,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"zur Halle sich wendend","translation":"turning towards the hall","literalText":true,"sourceStartIndex":18,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Euch beiden meld' ich,\nwie ich Brünnhild' band.","translation":"I'm reporting to both of you,\nhow I bound Brünnhild'.","literalText":true,"sourceStartIndex":19,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Gutrune tritt ihm aus der Halle entgegen","translation":"Gutrune steps out of the hall to meet him.","literalText":true,"sourceStartIndex":21,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Heiss' mich willkommen, Gibichskind!\nEin guter Bote bin ich dir.","translation":"Welcome me, Gibichskind!\nI am a good messenger to you.","literalText":true,"sourceStartIndex":22,"sourceLineCount":2},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Freia grüsse dich zu aller Frauen Ehre!","translation":"Freia, greetings to you on the honor of all women!","literalText":true,"sourceStartIndex":24,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Frei und hold sei nun mir Frohem:\nzum Weib gewann ich dich heut'.","translation":"Be free and sweet now to me, joyful one:\nI won you as my wife today.","literalText":true,"sourceStartIndex":25,"sourceLineCount":2},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"So folgt Brünnhild' meinem Bruder?","translation":"So Brünnhilde follows my brother?","literalText":true,"sourceStartIndex":27,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Leicht ward die Frau ihm gefreit.","translation":"The woman was easily wed to him.","literalText":true,"sourceStartIndex":28,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Sengte das Feuer ihn nicht?","translation":"Didn't the fire scorch him?","literalText":true,"sourceStartIndex":29,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Ihn hätt' es auch nicht versehrt,\ndoch ich durchschritt es für ihn,\nda dich ich wollt' erwerben.","translation":"It wouldn't have harmed him either,\nbut I went through it for him,\n'because I wanted to acquire you.'","literalText":true,"sourceStartIndex":30,"sourceLineCount":3},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Und dich hat es verschont?","translation":"And it spared you?","literalText":true,"sourceStartIndex":33,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Mich freute die schwelende Brunst.","translation":"I was pleased by the smoldering lust.","literalText":true,"sourceStartIndex":34,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Hielt Brünnhild' dich für Gunther?","translation":"Did Brünnhilde mistake you for Gunther?","literalText":true,"sourceStartIndex":35,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Ihm glich ich auf ein Haar:\nder Tarnhelm wirkte das,\nwie Hagen tüchtig es wies.","translation":"I looked exactly like him:\nThe invisibility helmet had that effect.\nas Hagen diligently demonstrated.","literalText":true,"sourceStartIndex":36,"sourceLineCount":3},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Dir gab ich guten Rat.","translation":"I gave you good advice.","literalText":true,"sourceStartIndex":39,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"So zwangst du das kühne Weib?","translation":"So you force the bold woman?","literalText":true,"sourceStartIndex":40,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Sie wich - Gunthers Kraft.","translation":"She yielded – Gunther's power.","literalText":true,"sourceStartIndex":41,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Und vermählte sie sich dir?","translation":"And did she marry you?","literalText":true,"sourceStartIndex":42,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Ihrem Mann gehorchte Brünnhild'\neine volle bräutliche Nacht.","translation":"Brünnhild obeyed her husband.\na full bridal night.","literalText":true,"sourceStartIndex":43,"sourceLineCount":2},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Als ihr Mann doch galtest du?","translation":"You were considered her husband, weren't you?","literalText":true,"sourceStartIndex":45,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Bei Gutrune weilte Siegfried.","translation":"Siegfried was staying with Gutrune.","literalText":true,"sourceStartIndex":46,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Doch zur Seite war ihm Brünnhild'?","translation":"But Brünnhilde was by his side?","literalText":true,"sourceStartIndex":47,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"auf sein Schwert deutend","translation":"pointing at his sword","literalText":true,"sourceStartIndex":48,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Zwischen Ost und West der Nord:\nso nah - war Brünnhild' ihm fern.","translation":"Between East and West of the North:\nSo close - Brünnhilde was far away from him.","literalText":true,"sourceStartIndex":49,"sourceLineCount":2},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Wie empfing Gunther sie nun von dir?","translation":"How did Gunther receive her from you?","literalText":true,"sourceStartIndex":51,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Durch des Feuers verlöschende Lohe,\nim Frühnebel vom Felsen folgte sie mir zu Tal;\ndem Strande nah,\nflugs die Stelle tauschte Gunther mit mir:\ndurch des Geschmeides Tugend\nwünscht' ich mich schnell hieher.\nEin starker Wind nun treibt\ndie Trauten den Rhein herauf:\ndrum rüstet jetzt den Empfang!","translation":"Through the dying embers of the fire,\nShe followed me down the valley from the rock in the early morning mist;\nnear the beach,\nGunther and I quickly swapped places:\nthrough the virtue of the jewelry\nI wish I could get here quickly.\nA strong wind is now driving\nthe Trauten up the Rhine:\nTherefore, upgrade your reception now!","literalText":true,"sourceStartIndex":52,"sourceLineCount":9},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Siegfried, mächtigster Mann!\nWie fasst mich Furcht vor dir!","translation":"Siegfried, most powerful man!\nHow fear of you grips me!","literalText":true,"sourceStartIndex":61,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"von der Höhe im Hintergrunde den Fluss hinabspähend","translation":"peering down the river from the height in the background","literalText":true,"sourceStartIndex":63,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"In der Ferne seh' ich ein Segel.","translation":"In the distance I see a sail.","literalText":true,"sourceStartIndex":64,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"So sagt dem Boten Dank!","translation":"So say thank you to the messenger!","literalText":true,"sourceStartIndex":65,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Lasset uns sie hold empfangen,\ndass heiter sie und gern hier weile!\nDu, Hagen, minnig rufe die Mannen\nnach Gibichs Hof zur Hochzeit!\nFrohe Frauen ruf' ich zum Fest:\nder Freudigen folgen sie gern.","translation":"Let us welcome them warmly,\nthat she is cheerful and enjoys being here!\nYou, Hagen, lovingly call the men\nTo Gibich's farm for the wedding!\nI call happy women to the festival:\nThey gladly follow the joyful.","literalText":true,"sourceStartIndex":66,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"nach der Halle schreitend, wendet sie sich wieder um","translation":"Walking towards the hall, she turns around again.","literalText":true,"sourceStartIndex":72,"sourceLineCount":1},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Rastest du, schlimmer Held?","translation":"Are you losing it, you terrible hero?","literalText":true,"sourceStartIndex":73,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Dir zu helfen, ruh' ich aus.","translation":"To help you, I rest.","literalText":true,"sourceStartIndex":74,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Er reicht ihr die Hand und geht mit ihr in die Halle","translatedTitle":"He extends his hand to her and goes with her into the hall.","participants":[],"sourceStartIndex":75,"sourceLineCount":1,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er reicht ihr die Hand und geht mit ihr in die Halle","translation":"He extends his hand to her and goes with her into the hall.","literalText":true,"sourceStartIndex":75,"sourceLineCount":1}]}]},{"number":4,"originalHeading":"DRITTE SZENE","translatedHeading":"Fourth Scene","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Hoiho! Hoihohoho!","translatedTitle":"Hoiho! Hoihohoho!","participants":["HAGEN","DIE MANNEN","EIN MANN","ZEHN WEITERE","ACHT MANNEN","VIER WEITERE","ALLE"],"sourceStartIndex":0,"sourceLineCount":75,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"hat einen Felsstein in der Höhe des Hintergrundes erstiegen; dort setzt er, der Landseite zugewendet, sein Stierhorn zum Blasen an","translation":"He has climbed a rock high in the background; there, facing the landward side, he sets his bull's horn to blow it.","literalText":true,"sourceStartIndex":0,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Hoiho! Hoihohoho!\nIhr Gibichsmannen, machet euch auf!\nWehe! Wehe! Waffen! Waffen!\nWaffen durchs Land! Gute Waffen!\nStarke Waffen! Scharf zum Streit.\nNot ist da! Not! Wehe! Wehe!\nHoiho! Hoihohoho!","translation":"Hoiho! Hoihohoho!\nYou Gibichsmen, get up!\nWoe betide! Woe bet! Weapons! Weapons!\nWeapons across the country! Good weapons!\nPowerful weapons! Sharp for a fight.\nEmergency! Emergency! Woe! Woe!\nHoiho! Hoihohoho!","literalText":true,"sourceStartIndex":1,"sourceLineCount":7},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Hagen bleibt immer in seiner Stellung auf der Anhöhe. Er bläst abermals. Aus verschiedenen Gegenden vom Lande her antworten Heerhörner. Auf den verschiedenen Höhenpfaden stürmen in Hast und Eile gewaffnete Mannen herbei, erst einzelne, dann immer mehrere zusammen, welche sich dann auf dem Uferraum vor der Halle anhäufen\nerst einzelne, dann immer neu hinzukommende","translation":"Hagen remains in his position on the hilltop. He blows his horn again. From various parts of the countryside, army horns answer. Along the different paths up the hills, armed men rush forward in haste, first individually, then in groups, gathering on the riverbank in front of the hall.\nFirst individual ones, then increasingly more.","literalText":true,"sourceStartIndex":8,"sourceLineCount":2},{"speaker":"DIE MANNEN","speakerTranslation":"DIE MANNEN","original":"Was tost das Horn?\nWas ruft es zu Heer?\nWir kommen mit Wehr,\nWir kommen mit Waffen!\nHagen! Hagen!\nHoiho! Hoiho!\nWelche Not ist da?\nWelcher Feind ist nah?\nWer gibt uns Streit?\nIst Gunther in Not?\nWir kommen mit Waffen,\nmit scharfer Wehr.\nHoiho! Ho! Hagen!","translation":"What is the horn blaring?\nWhat is it calling to arms?\nWe're coming with force,\nWe're coming with weapons!\nHagen! Hagen!\nHoiho! Hoiho!\nWhat kind of emergency is there?\nWhich enemy is near?\nWho is starting a fight with us?\nIs Gunther in trouble?\nWe are coming with weapons,\nwith sharp weaponry.\nHoiho! Ho! Hagen!","literalText":true,"sourceStartIndex":10,"sourceLineCount":13},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"immer von der Anhöhe herab","translation":"always from the hilltop","literalText":true,"sourceStartIndex":23,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Rüstet euch wohl und rastet nicht;\nGunther sollt ihr empfahn:\nein Weib hat der gefreit.","translation":"Prepare yourselves well and do not rest;\nGunther should be received by you:\nHe married a woman.","literalText":true,"sourceStartIndex":24,"sourceLineCount":3},{"speaker":"DIE MANNEN","speakerTranslation":"DIE MANNEN","original":"Drohet ihm Not?\nDrängt ihn der Feind?","translation":"Is he in danger?\nIs he being pressured by the enemy?","literalText":true,"sourceStartIndex":27,"sourceLineCount":2},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Ein freisliches Weib führet er heim.","translation":"He brings home a free woman.","literalText":true,"sourceStartIndex":29,"sourceLineCount":1},{"speaker":"DIE MANNEN","speakerTranslation":"DIE MANNEN","original":"Ihm folgen der Magen feindliche Mannen?","translation":"Are hostile men following him?","literalText":true,"sourceStartIndex":30,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Einsam fährt er: keiner folgt.","translation":"He drives alone: ​​no one follows.","literalText":true,"sourceStartIndex":31,"sourceLineCount":1},{"speaker":"DIE MANNEN","speakerTranslation":"DIE MANNEN","original":"So bestand er die Not?\nSo bestand er den Kampf?\nSag' es an!","translation":"So he survived the ordeal?\nSo he survived the fight?\nSay it!","literalText":true,"sourceStartIndex":32,"sourceLineCount":3},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Der Wurmtöter wehrte der Not:\nSiegfried, der Held, der schuf ihm Heil!","translation":"The worm killer averted the danger:\nSiegfried, the hero, brought him salvation!","literalText":true,"sourceStartIndex":35,"sourceLineCount":2},{"speaker":"EIN MANN","speakerTranslation":"EIN MANN","original":"Was soll ihm das Heer nun noch helfen?","translation":"What good is the army supposed to do for him now?","literalText":true,"sourceStartIndex":37,"sourceLineCount":1},{"speaker":"ZEHN WEITERE","speakerTranslation":"ZEHN WEITERE","original":"Was hilft ihm nun das Heer?","translation":"What good is the army to him now?","literalText":true,"sourceStartIndex":38,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Starke Stiere sollt ihr schlachten;\nam Weihstein fliesse Wotan ihr Blut!","translation":"You shall slaughter strong bulls;\nMay Wotan's blood flow at the holy stone!","literalText":true,"sourceStartIndex":39,"sourceLineCount":2},{"speaker":"EIN MANN","speakerTranslation":"EIN MANN","original":"Was, Hagen, was heissest du uns dann?","translation":"What, Hagen, what do you call us then?","literalText":true,"sourceStartIndex":41,"sourceLineCount":1},{"speaker":"ACHT MANNEN","speakerTranslation":"ACHT MANNEN","original":"Was heissest du uns dann?","translation":"What do you mean by \"us\" then?","literalText":true,"sourceStartIndex":42,"sourceLineCount":1},{"speaker":"VIER WEITERE","speakerTranslation":"VIER WEITERE","original":"Was soll es dann?","translation":"So what's the point then?","literalText":true,"sourceStartIndex":43,"sourceLineCount":1},{"speaker":"ALLE","speakerTranslation":"ALLE","original":"Was heissest du uns dann?","translation":"What do you mean by \"us\" then?","literalText":true,"sourceStartIndex":44,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Einen Eber fällen sollt ihr für Froh!\nEinen stämmigen Bock stechen für Donner!\nSchafe aber schlachtet für Fricka,\ndass gute Ehe sie gebe!","translation":"You shall cut down a boar for Froh!\nTo stab a stout buck for thunder!\nBut slaughter sheep for Fricka,\nMay good marriages be granted!","literalText":true,"sourceStartIndex":45,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"mit immer mehr ausbrechender Heiterkeit","translation":"with ever-increasing bursts of gaiety","literalText":true,"sourceStartIndex":49,"sourceLineCount":1},{"speaker":"DIE MANNEN","speakerTranslation":"DIE MANNEN","original":"Schlugen wir Tiere,\nwas schaffen wir dann?","translation":"If we beat animals,\nWhat will we achieve then?","literalText":true,"sourceStartIndex":50,"sourceLineCount":2},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Das Trinkhorn nehmt,\nvon trauten Frau'n\nmit Met und Wein wonnig gefüllt!","translation":"Take the drinking horn,\nfrom trusted women\nFilled with mead and wine, blissfully filled!","literalText":true,"sourceStartIndex":52,"sourceLineCount":3},{"speaker":"DIE MANNEN","speakerTranslation":"DIE MANNEN","original":"Das Trinkhorn zur Hand,\nwie halten wir es dann?","translation":"Grab the drinking horn,\nSo, what do we do then?","literalText":true,"sourceStartIndex":55,"sourceLineCount":2},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Rüstig gezecht, bis der Rausch euch zähmt!\nAlles den Göttern zu Ehren,\ndass gute Ehe sie geben!","translation":"Drink heartily until the intoxication tames you!\nAll for the glory of the gods,\nMay they give you a good marriage!","literalText":true,"sourceStartIndex":57,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"brechen in ein schallendes Gelächter aus","translation":"break into a roar of laughter","literalText":true,"sourceStartIndex":60,"sourceLineCount":1},{"speaker":"DIE MANNEN","speakerTranslation":"DIE MANNEN","original":"Gross Glück und Heil lacht nun dem Rhein,\nda Hagen, der Grimme, so lustig mag sein!\nDer Hagedorn sticht nun nicht mehr;\nzum Hochzeitsrufer ward er bestellt.","translation":"Great happiness and salvation now smile upon the Rhine,\nHagen, the Grim, may be so funny!\nThe hawthorn no longer stings;\nHe was appointed as the wedding herald.","literalText":true,"sourceStartIndex":61,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"der immer sehr ernst geblieben, ist zu den Mannen herabgestiegen und steht jetzt unter ihnen","translation":"He, who always remained very serious, has descended to the men and now stands among them.","literalText":true,"sourceStartIndex":65,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Nun lasst das Lachen, mut'ge Mannen!\nEmpfangt Gunthers Braut!\nBrünnhilde naht dort mit ihm.","translation":"Now stop laughing, brave men!\nWelcome Gunther's bride!\nBrünnhilde approaches there with him.","literalText":true,"sourceStartIndex":66,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er deutet die Mannen nach dem Rhein hin: diese eilen zum Teil nach der Anhöhe, während andere sich am Ufer aufstellen, um die Ankommenden zu erblicken","translation":"He gestures towards the Rhine for the men: some hurry towards the hill, while others position themselves on the bank to watch the arrivals.","literalText":true,"sourceStartIndex":69,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"näher zu einigen Mannen tretend\nHold seid der Herrin,\nhelfet ihr treu:\ntraf sie ein Leid,\nrasch seid zur Rache!","translation":"approaching some men\nBe gracious to the mistress,\nHelp her faithfully:\nShe suffered a misfortune\nBe swift to exact revenge!","literalText":true,"sourceStartIndex":70,"sourceLineCount":5}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Heil! Heil!","translatedTitle":"Hail! Hail!","participants":["DIE MANNEN"],"sourceStartIndex":75,"sourceLineCount":7,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er wendet sich langsam zur Seite, in den Hintergrund. Während des Folgenden kommt der Nachen mit Gunther und Brünnhilde auf dem Rheine an.\ndiejenigen, welche von der Höhe ausgeblickt hatten, kommen zum Ufer herab","translation":"He slowly turns to the side, into the background. Meanwhile, the boat carrying Gunther and Brünnhilde arrives on the Rhine.\nThose who had looked out from the height came down to the shore.","literalText":true,"sourceStartIndex":75,"sourceLineCount":2},{"speaker":"DIE MANNEN","speakerTranslation":"DIE MANNEN","original":"Heil! Heil!\nWillkommen! Willkommen!","translation":"Hail! Hail!\nWelcome! Welcome!","literalText":true,"sourceStartIndex":77,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Einige der Mannen springen in den Fluss und ziehen den Kahn an das Land. Alles drängt sich immer dichter an das Ufer","translation":"Some of the men jump into the river and pull the boat towards the shore. Everyone crowds closer and closer to the bank.","literalText":true,"sourceStartIndex":79,"sourceLineCount":1},{"speaker":"DIE MANNEN","speakerTranslation":"DIE MANNEN","original":"Willkommen, Gunther!\nHeil! Heil!","translation":"Welcome, Gunther!\nHail! Hail!","literalText":true,"sourceStartIndex":80,"sourceLineCount":2}]}]},{"number":5,"originalHeading":"VIERTE SZENE","translatedHeading":"Fifth Scene","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Heil dir, Gunther!","translatedTitle":"Hail to you, Gunther!","participants":["DIE MANNEN","GUNTHER","MANNEN UND FRAUEN","SIEGFRIED","BRÜNNHILDE","HAGEN"],"sourceStartIndex":0,"sourceLineCount":74,"turns":[{"speaker":"DIE MANNEN","speakerTranslation":"DIE MANNEN","original":"Heil dir, Gunther!\nHeil dir und deiner Braut!\nWillkommen!","translation":"Hail to you, Gunther!\nHail to you and your bride!\nWelcome!","literalText":true,"sourceStartIndex":0,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie schlagen die Waffen tosend zusammen\nBrünnhilde, welche bleich und gesenkten Blickes ihm folgt, den Mannen vorstellend","translation":"They clash their weapons together with a thunderous roar.\nBrünnhilde, who follows him pale and with downcast eyes, introduces the men","literalText":true,"sourceStartIndex":3,"sourceLineCount":2},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Brünnhild', die hehrste Frau,\nbring' ich euch her zum Rhein.\nEin edleres Weib ward nie gewonnen.\nDer Gibichungen Geschlecht,\ngaben die Götter ihm Gunst,\nzum höchsten Ruhm rag' es nun auf!","translation":"Brünnhild', the noblest woman,\nI'll bring you here to the Rhine.\nA nobler woman was never won.\nThe Gibichung genus\nThe gods gave him favor,\nNow let it rise up to the highest glory!","literalText":true,"sourceStartIndex":5,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"feierlich an ihre Waffen schlagend","translation":"solemnly striking their weapons","literalText":true,"sourceStartIndex":11,"sourceLineCount":1},{"speaker":"DIE MANNEN","speakerTranslation":"DIE MANNEN","original":"Heil! Heil dir,\nglücklicher Gibichung!","translation":"Hail! Hail to you,\nHappy Gibichung!","literalText":true,"sourceStartIndex":12,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Gunther geleitet Brünnhilde, die nie aufblickt, zur Halle, aus welcher jetzt Siegfried und Gutrune, von Frauen begleitet, heraustreten\nhält vor der Halle an","translation":"Gunther leads Brünnhilde, who never looks up, to the hall from which Siegfried and Gutrune, accompanied by women, now emerge.\nstops in front of the hall","literalText":true,"sourceStartIndex":14,"sourceLineCount":2},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Gegrüsst sei, teurer Held;\ngegrüsst, holde Schwester!\nDich seh' ich froh ihm zur Seite,\nder dich zum Weib gewann.\nZwei sel'ge Paare\nseh ich hier prangen:","translation":"Hail, dear hero;\nGreetings, lovely sister!\nI'm glad to see you by his side,\nwho won you as his wife.\nTwo blessed couples\nI see it displayed here:","literalText":true,"sourceStartIndex":16,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"er führt Brünnhilde näher heran","translation":"He brings Brünnhilde closer","literalText":true,"sourceStartIndex":22,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Brünnhild' und Gunther,\nGutrun' und Siegfried!","translation":"Brünnhild' and Gunther,\nGutrun and Siegfried!","literalText":true,"sourceStartIndex":23,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Brünnhilde schlägt erschreckt die Augen auf und erblickt Siegfried; wie in Erstaunen bleibt ihr Blick auf ihn gerichtet. Gunther, welcher Brünnhildes heftig zuckende Hand losgelassen hat, sowie alle übrigen zeigen starre Betroffenheit über Brünnhildes Benehmen","translation":"Brünnhilde opened her eyes in alarm and saw Siegfried; her gaze remained fixed on him as if in astonishment. Gunther, who had released Brünnhilde's violently twitching hand, and all the others showed rigid shock at Brünnhilde's behavior.","literalText":true,"sourceStartIndex":25,"sourceLineCount":1},{"speaker":"MANNEN UND FRAUEN","speakerTranslation":"MANNEN UND FRAUEN","original":"Was ist ihr? Ist sie entrückt?","translation":"What's wrong with her? Is she ecstatic?","literalText":true,"sourceStartIndex":26,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Brünnhilde beginnt zu zittern\ngeht ruhig einige Schritte auf Brünnhilde zu","translation":"Brünnhilde begins to tremble.\nTake a few steps towards Brünnhilde.","literalText":true,"sourceStartIndex":27,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Was müht Brünnhildes Blick?","translation":"What troubles Brünnhilde's gaze?","literalText":true,"sourceStartIndex":29,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"kaum ihrer mächtig","translation":"barely their might","literalText":true,"sourceStartIndex":30,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Siegfried... hier...! Gutrune...?","translation":"Siegfried... here...! Gutrune...?","literalText":true,"sourceStartIndex":31,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Gunthers milde Schwester:\nmir vermählt wie Gunther du.","translation":"Gunther's gentle sister:\nMarried to me like Gunther you.","literalText":true,"sourceStartIndex":32,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"furchtbar heftig","translation":"terribly intense","literalText":true,"sourceStartIndex":34,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Ich.... Gunther... ? Du lügst!","translation":"Me... Gunther...? You're lying!","literalText":true,"sourceStartIndex":35,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie schwankt und droht umzusinken: Siegfried, ihr zunächst, stützt sie","translation":"She wavers and threatens to topple over: Siegfried, her first, supports her.","literalText":true,"sourceStartIndex":36,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Mir schwindet das Licht ....","translation":"The light is fading for me....","literalText":true,"sourceStartIndex":37,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Sie blickt in seinen Armen matt zu Siegfried auf","translation":"She gazes dully at Siegfried from his arms.","literalText":true,"sourceStartIndex":38,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Siegfried - kennt mich nicht!","translation":"Siegfried doesn't know me!","literalText":true,"sourceStartIndex":39,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Gunther, deinem Weib ist übel!","translation":"Gunther, your wife feels sick!","literalText":true,"sourceStartIndex":40,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Gunther tritt hinzu","translation":"Gunther joins them","literalText":true,"sourceStartIndex":41,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Erwache, Frau!\nHier steht dein Gatte.","translation":"Wake up, woman!\nYour husband is standing here.","literalText":true,"sourceStartIndex":42,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"erblickt am ausgestreckten Finger Siegfrieds den Ring und schrickt mit furchtbarer Heftigkeit auf","translation":"He sees the ring on Siegfried's outstretched finger and recoils with terrible fright.","literalText":true,"sourceStartIndex":44,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Ha! - Der Ring -\nan seiner Hand!\nEr - ? Siegfried?","translation":"Ha! - The Ring -\non his hand!\nHe - ? Siegfried?","literalText":true,"sourceStartIndex":45,"sourceLineCount":3},{"speaker":"MANNEN UND FRAUEN","speakerTranslation":"MANNEN UND FRAUEN","original":"Was ist?","translation":"What is?","literalText":true,"sourceStartIndex":48,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"aus dem Hintergrunde unter die Mannen tretend","translation":"emerging from the background to join the men","literalText":true,"sourceStartIndex":49,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Jetzt merket klug,\nwas die Frau euch klagt!","translation":"Now, take note,\nWhat the woman is complaining about!","literalText":true,"sourceStartIndex":50,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"sucht sich zu ermannen, indem sie die schrecklichste Aufregung gewaltsam zurückhält","translation":"She tries to compose herself by forcibly suppressing the most terrible excitement.","literalText":true,"sourceStartIndex":52,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Einen Ring sah ich an deiner Hand, -\nnicht dir gehört er,\nihn entriss mir","translation":"I saw a ring on your hand, -\nIt doesn't belong to you.\nHe tore him from me","literalText":true,"sourceStartIndex":53,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"auf Gunther deutend","translation":"pointing towards Gunther","literalText":true,"sourceStartIndex":56,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"dieser Mann!\nWie mochtest von ihm\nden Ring du empfahn?","translation":"That man!\nHow did you like him?\nthe ring you received?","literalText":true,"sourceStartIndex":57,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"aufmerksam den Ring an seiner Hand betrachtend","translation":"attentively examining the ring on his hand","literalText":true,"sourceStartIndex":60,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Den Ring empfing ich nicht von ihm.","translation":"I did not receive the ring from him.","literalText":true,"sourceStartIndex":61,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"zu Gunther","translation":"to Gunther","literalText":true,"sourceStartIndex":62,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Nahmst du von mir den Ring,\ndurch den ich dir vermählt;\nso melde ihm dein Recht,\nfordre zurück das Pfand!","translation":"Did you take the ring from me?\nthrough whom I betrothed you;\nSo inform him of your right,\nDemand your deposit back!","literalText":true,"sourceStartIndex":63,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"in grosser Verwirrung","translation":"in great confusion","literalText":true,"sourceStartIndex":67,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Den Ring? Ich gab ihm keinen:\ndoch - kennst du ihn auch gut?","translation":"The ring? I didn't give him one.\nBut do you know him well too?","literalText":true,"sourceStartIndex":68,"sourceLineCount":2},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Wo bärgest du den Ring,\nden du von mir erbeutet?","translation":"Where do you keep the ring?\nwhich you looted from me?","literalText":true,"sourceStartIndex":70,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Gunther schweigt in höchster Betroffenheit\nwütend auffahrend","translation":"Gunther remains silent, deeply affected.\nangrily erupting","literalText":true,"sourceStartIndex":72,"sourceLineCount":2}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Ha! - Dieser war es,","translatedTitle":"Ha! - This was it!","participants":["BRÜNNHILDE","SIEGFRIED","HAGEN","GUTRUNE","MANNEN UND FRAUEN","GUNTHER","FRAUEN","MANNEN","DIE MANNEN","DIE FRAUEN"],"sourceStartIndex":74,"sourceLineCount":73,"turns":[{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Ha! - Dieser war es,\nder mir den Ring entriss:\nSiegfried, der trugvolle Dieb!","translation":"Ha! - This was it!\nwho snatched the ring from me:\nSiegfried, the treacherous thief!","literalText":true,"sourceStartIndex":74,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Alles blickt erwartungsvoll auf Siegfried, welcher über der Betrachtung des Ringes in fernes Sinnen entrückt ist","translation":"Everyone looks expectantly at Siegfried, who is lost in thought as he contemplates the ring.","literalText":true,"sourceStartIndex":77,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Von keinem Weib kam mir der Reif;\nnoch war's ein Weib, dem ich ihn abgewann:\ngenau erkenn' ich des Kampfes Lohn,\nden vor Neidhöhl' einst ich bestand,\nals den starken Wurm ich erschlug.","translation":"My fertility came from no woman;\nIt was still a woman from whom I won him:\nI know exactly the reward of the struggle,\nthe one I once stood before Neidhöhl\nwhen I slew the strong worm.","literalText":true,"sourceStartIndex":78,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"wischen sie tretend","translation":"wipe while stepping","literalText":true,"sourceStartIndex":83,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Brünnhild', kühne Frau,\nkennst du genau den Ring?\nIst's der, den du Gunthern gabst,\nso ist er sein, -\nund Siegfried gewann ihn durch Trug,\nden der Treulose büssen sollt'!","translation":"Brünnhild', bold woman,\nDo you know the ring exactly?\nIs this the one you gave to Gunther?\nThat's how he is, -\nand Siegfried won him through deception,\nwhom the faithless man should pay for!","literalText":true,"sourceStartIndex":84,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"in furchtbarstem Schmerze aufschreiend","translation":"screaming in the most terrible pain","literalText":true,"sourceStartIndex":90,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Betrug! Betrug! Schändlichster Betrug!\nVerrat! Verrat! - Wie noch nie er gerächt!","translation":"Fraud! Fraud! Most shameful fraud!\nBetrayal! Betrayal! - He was avenged like never before!","literalText":true,"sourceStartIndex":91,"sourceLineCount":2},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Verrat? An wem?","translation":"Betrayal? Of whom?","literalText":true,"sourceStartIndex":93,"sourceLineCount":1},{"speaker":"MANNEN UND FRAUEN","speakerTranslation":"MANNEN UND FRAUEN","original":"Verrat? Verrat?","translation":"Betrayal? Betrayal?","literalText":true,"sourceStartIndex":94,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Heil'ge Götter, himmlische Lenker!\nRauntet ihr dies in eurem Rat?\nLehrt ihr mich Leiden, wie keiner sie litt?\nSchuft ihr mir Schmach, wie nie sie geschmerzt?\nRatet nun Rache, wie nie sie gerast!\nZündet mir Zorn, wie noch nie er gezähmt!\nHeisset Brünnhild' ihr Herz zu zerbrechen,\nden zu zertrümmern, der sie betrog!","translation":"Holy gods, heavenly rulers!\nDid you whisper this in your council?\nAre you teaching me to suffer as no one has ever suffered?\nDid you inflict upon me shame such as I have never known before?\nNow guess revenge, as never before has it raged!\nIgnite my wrath like never before tamed!\nDoes Brünnhilde urge you to break her heart?\nto crush the one who betrayed them!","literalText":true,"sourceStartIndex":95,"sourceLineCount":8},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Brünnhild', Gemahlin!\nMäss'ge dich!","translation":"Brünnhild', wife!\nModerate yourself!","literalText":true,"sourceStartIndex":103,"sourceLineCount":2},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Weich' fern, Verräter!\nSelbst Verrat'ner -\nWisset denn alle: nicht ihm,\ndem Manne dort bin ich vermählt.","translation":"Get away, traitor!\nEven traitors -\nKnow this, all of you: not him,\nI am married to that man.","literalText":true,"sourceStartIndex":105,"sourceLineCount":4},{"speaker":"FRAUEN","speakerTranslation":"FRAUEN","original":"Siegfried? Gutruns Gemahl?","translation":"Siegfried? Gutrun's husband?","literalText":true,"sourceStartIndex":109,"sourceLineCount":1},{"speaker":"MANNEN","speakerTranslation":"MANNEN","original":"Gutruns Gemahl?","translation":"Gutrun's husband?","literalText":true,"sourceStartIndex":110,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Er zwang mir Lust und Liebe ab.","translation":"He forced lust and love from me.","literalText":true,"sourceStartIndex":111,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Achtest du so der eignen Ehre?\nDie Zunge, die sie lästert,\nmuss ich der Lüge sie zeihen?\nHört, ob ich Treue brach!\nBlutbrüderschaft\nhab' ich Gunther geschworen:\nNotung, das werte Schwert,\nwahrte der Treue Eid;\nmich trennte seine Schärfe\nvon diesem traur'gen Weib.","translation":"Do you respect your own honor that way?\nThe tongue that blasphemes her,\nDo I have to accuse her of lying?\nListen, have I broken my loyalty?\nBlood Brotherhood\nI swore to Gunther:\nNottung, the precious sword,\nkept his oath of loyalty;\nHis sharpness separated me\nfrom this sad woman.","literalText":true,"sourceStartIndex":112,"sourceLineCount":10},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Du listiger Held, sieh', wie du lügst!\nWie auf dein Schwert du schlecht dich berufst!\nWohl kenn' ich seine Schärfe,\ndoch kenn' auch die Scheide,\ndarin so wonnig ruht' an der Wand\nNotung, der treue Freund,\nals die Traute sein Herr sich gefreit.","translation":"You cunning hero, look how you lie!\nHow poorly you rely on your sword!\nI am well aware of its sharpness,\nBut I also know the vagina,\nresting so blissfully on the wall\nNothung, the faithful friend,\nwhen the bride darled her master.","literalText":true,"sourceStartIndex":122,"sourceLineCount":7},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"in lebhafter Entrüstung zusammentretend","translation":"assembling in lively indignation","literalText":true,"sourceStartIndex":129,"sourceLineCount":1},{"speaker":"DIE MANNEN","speakerTranslation":"DIE MANNEN","original":"Wie? Brach er die Treue?\nTrübte er Gunthers Ehre?","translation":"How? Did he break his loyalty?\nDid he tarnish Gunther's honor?","literalText":true,"sourceStartIndex":130,"sourceLineCount":2},{"speaker":"DIE FRAUEN","speakerTranslation":"DIE FRAUEN","original":"Brach er die Treue?","translation":"Did he break his loyalty?","literalText":true,"sourceStartIndex":132,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"zu Siegfried","translation":"to Siegfried","literalText":true,"sourceStartIndex":133,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Geschändet wär' ich, schmählich bewahrt,\ngäbst du die Rede nicht ihr zurück!","translation":"I would be defiled, shamefully preserved,\nDon't give the speech back to her!","literalText":true,"sourceStartIndex":134,"sourceLineCount":2},{"speaker":"GUTRUNE","speakerTranslation":"GUTRUNE","original":"Treulos, Siegfried, sannest du Trug?\nBezeuge, dass jene falsch dich zeiht!","translation":"Faithless, Siegfried, are you pondering deceit?\nTestify that she is accusing you falsely!","literalText":true,"sourceStartIndex":136,"sourceLineCount":2},{"speaker":"DIE MANNEN","speakerTranslation":"DIE MANNEN","original":"Reinige dich, bist du im Recht!\nSchweige die Klage!\nSchwöre den Eid!","translation":"Cleanse yourself, and you are in the right!\nSilence the complaint!\nSwear the oath!","literalText":true,"sourceStartIndex":138,"sourceLineCount":3},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Schweig' ich die Klage,\nschwör' ich den Eid:\nwer von euch wagt seine Waffe daran?","translation":"If I silence the complaint,\nI swear this oath:\nWhich of you dares to use your weapon on it?","literalText":true,"sourceStartIndex":141,"sourceLineCount":3},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Meines Speeres Spitze wag' ich daran:\nsie wahr' in Ehren den Eid.","translation":"I dare to use the tip of my spear on it:\nShe honored the oath.","literalText":true,"sourceStartIndex":144,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Die Mannen schliessen einen Ring um Siegfried und Hagen. Hagen hält den Speer hin; Siegfried legt zwei Finger seiner rechten Hand auf die Speerspitze","translation":"The men form a ring around Siegfried and Hagen. Hagen holds out the spear; Siegfried places two fingers of his right hand on the spearhead.","literalText":true,"sourceStartIndex":146,"sourceLineCount":1}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Helle Wehr! Heilige Waffe!","translatedTitle":"Bright weapon! Holy weapon!","participants":["SIEGFRIED","BRÜNNHILDE","DIE MANNEN"],"sourceStartIndex":147,"sourceLineCount":55,"turns":[{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Helle Wehr! Heilige Waffe!\nHilf meinem ewigen Eide!\nBei des Speeres Spitze sprech' ich den Eid:\nSpitze, achte des Spruchs!\nWo Scharfes mich schneidet,\nschneide du mich;\nwo der Tod mich soll treffen,\ntreffe du mich:\nklagte das Weib dort wahr,\nbrach ich dem Bruder den Eid!","translation":"Bright weapon! Holy weapon!\nHelp my eternal oath!\nBy the spear's tip I swear the oath:\nTip, note the saying!\nWhere sharp things cut me,\nCut me;\nwhere death should meet me,\nmeet me:\nThe woman there truly complained,\nI broke my oath to my brother!","literalText":true,"sourceStartIndex":147,"sourceLineCount":10},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"tritt wütend in den Ring, reisst Siegfrieds Hand vom Speere hinweg und fasst dafür mit der ihrigen die Spitze","translation":"She angrily steps into the ring, tears Siegfried's hand away from the spear, and grasps the tip with her own.","literalText":true,"sourceStartIndex":157,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Helle Wehr! Heilige Waffe!\nHilf meinem ewigen Eide!\nBei des Speeres Spitze sprech' ich den Eid:\nSpitze, achte des Spruchs!\nIch weihe deine Wucht,\ndass sie ihn werfe!\nDeine Schärfe segne ich,\ndass sie ihn schneide:\ndenn, brach seine Eide er all',\nschwur Meineid jetzt dieser Mann!","translation":"Bright weapon! Holy weapon!\nHelp my eternal oath!\nBy the spear's tip I swear the oath:\nTip, note the saying!\nI consecrate your power,\nthat she throws him!\nI bless your sharpness,\nthat she cut him:\nfor, he broke all his oaths,\nThis man has now committed perjury!","literalText":true,"sourceStartIndex":158,"sourceLineCount":10},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"im höchsten Aufruhr","translation":"in the highest turmoil","literalText":true,"sourceStartIndex":168,"sourceLineCount":1},{"speaker":"DIE MANNEN","speakerTranslation":"DIE MANNEN","original":"Hilf, Donner, tose dein Wetter,\nzu schweigen die wütende Schmach!","translation":"Help, thunder, roar your weather,\nNot to mention the furious disgrace!","literalText":true,"sourceStartIndex":169,"sourceLineCount":2},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Gunther! Wehr' deinem Weibe,\ndas schamlos Schande dir lügt!\nGönnt ihr Weil' und Ruh',\nder wilden Felsenfrau,\ndass ihre freche Wut sich lege,\ndie eines Unholds arge List\nwider uns alle erregt!\nIhr Mannen, kehret euch ab!\nLasst das Weibergekeif'!\nAls Zage weichen wir gern,\ngilt es mit Zungen den Streit.","translation":"Gunther! Protect your wife,\nThat shameless lie to you!\nGive her time and peace,\nthe wild rock woman,\nthat their cheeky anger would subside,\nthe wicked cunning of a monster\nIt arouses us all!\nTurn away, you men!\nStop the women squabbling!\nAs timid people, we readily give way,\nThe argument must be resolved with tongues.","literalText":true,"sourceStartIndex":171,"sourceLineCount":11},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"er tritt dicht zu Gunther","translation":"he steps close to Gunther","literalText":true,"sourceStartIndex":182,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Glaub', mehr zürnt es mich als dich,\ndass schlecht ich sie getäuscht:\nder Tarnhelm, dünkt mich fast,\nhat halb mich nur gehehlt.\nDoch Frauengroll friedet sich bald:\ndass ich dir es gewann,\ndankt dir gewiss noch das Weib.","translation":"Believe me, it angers me more than you.\nthat I deceived her badly:\nthe Tarnhelm, it almost seems to me,\nhalf of me was only saved.\nBut the women's resentment soon subsides:\nthat I won it for you\nYour wife will surely thank you.","literalText":true,"sourceStartIndex":183,"sourceLineCount":7},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"er wendet sich wieder zu den Mannen","translation":"He turns back to the men.","literalText":true,"sourceStartIndex":190,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Munter, ihr Mannen!\nFolgt mir zum Mahl!","translation":"Cheers, you men!\nFollow me to the meal!","literalText":true,"sourceStartIndex":191,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"zu den Frauen","translation":"to the women","literalText":true,"sourceStartIndex":193,"sourceLineCount":1},{"speaker":"SIEGFRIED","speakerTranslation":"SIEGFRIED","original":"Froh zur Hochzeit, helfet, ihr Frauen!\nWonnige Lust lache nun auf!\nIn Hof und Hain,\nheiter vor allen sollt ihr heute mich sehn.\nWen die Minne freut,\nmeinem frohen Mute\ntu' es der Glückliche gleich!","translation":"Happy wedding, help, you women!\nLaughterful joy, now laugh aloud!\nIn Hof and Hain,\nToday you should see me cheerful above all others.\nThose who are pleased by love,\nmy cheerful spirit\nDo the same as the lucky one!","literalText":true,"sourceStartIndex":194,"sourceLineCount":7},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Er schlingt in ausgelassenem Übermute seinen Arm um Gutrune und zieht sie mit sich in die Halle fort. Die Mannen und Frauen, von seinem Beispiele hingerissen, folgen ihm nach. Die Bühne ist leer geworden. Nur Brünnhilde, Gunther und Hagen bleiben zurück. Gunther hat sich in tiefer Scham und furchtbarer Verstimmung mit verhülltem Gesichte abseits niedergesetzt. Brünnhilde, im Vordergrunde stehend, blickt Siegfried und Gutrune noch eine Zeitlang schmerzlich nach und senkt dann das Haupt","translation":"In unrestrained exuberance, he throws his arm around Gutrune and pulls her with him into the hall. The men and women, inspired by his example, follow him. The stage is now empty. Only Brünnhilde, Gunther, and Hagen remain. Gunther, overcome with shame and terrible distress, has sat down off to the side, his face veiled. Brünnhilde, standing in the foreground, gazes after Siegfried and Gutrune for a while with a pained expression, then bows her head.","literalText":true,"sourceStartIndex":201,"sourceLineCount":1}]}]},{"number":6,"originalHeading":"FÜNFTE SZENE","summary":"","sections":[{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Welches Unholds List liegt hier verhohlen?","translatedTitle":"What sinister plot lies hidden here?","participants":["BRÜNNHILDE","HAGEN","GUNTHER"],"sourceStartIndex":0,"sourceLineCount":75,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"in starrem Nachsinnen befangen","translation":"trapped in rigid contemplation","literalText":true,"sourceStartIndex":0,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Welches Unholds List liegt hier verhohlen?\nWelches Zaubers Rat regte dies auf?\nWo ist nun mein Wissen gegen dies Wirrsal?\nWo sind meine Runen gegen dies Rätsel?\nAch Jammer! Jammer! Weh', ach Wehe!\nAll mein Wissen wies ich ihm zu!\nIn seiner Macht hält er die Magd;\nin seinen Banden fasst er die Beute,\ndie, jammernd ob ihrer Schmach,\njauchzend der Reiche verschenkt!\nWer bietet mir nun das Schwert,\nmit dem ich die Bande zerschnitt'?","translation":"What sinister plot lies hidden here?\nWhich magic council was upset by this?\nWhere is my knowledge now compared to this confusion?\nWhere are my runes against this riddle?\nOh, what a pity! Shame! Woe, oh woe!\nI assigned all my knowledge to him!\nHe holds the maid in his power;\nHe captures the loot in his gangs,\nthose, lamenting their disgrace,\nThe rich man gives away his gifts with jubilation!\nWho will now offer me the sword?\nwith whom I cut the ties?","literalText":true,"sourceStartIndex":1,"sourceLineCount":12},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"dicht an sie herantretend","translation":"approaching her closely","literalText":true,"sourceStartIndex":13,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Vertraue mir, betrog'ne Frau!\nWer dich verriet, das räche ich.","translation":"Trust me, betrayed woman!\nI will avenge those who betrayed you.","literalText":true,"sourceStartIndex":14,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"matt sich umblickend","translation":"looking around dully","literalText":true,"sourceStartIndex":16,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"An wem?","translation":"To whom?","literalText":true,"sourceStartIndex":17,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"An Siegfried, der dich betrog.","translation":"To Siegfried, who betrayed you.","literalText":true,"sourceStartIndex":18,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"An Siegfried?... Du?","translation":"To Siegfried?... You?","literalText":true,"sourceStartIndex":19,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"bitter lächelnd","translation":"bitterly smiling","literalText":true,"sourceStartIndex":20,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Ein einz'ger Blick seines blitzenden Auges,\n- das selbst durch die Lügengestalt\nleuchtend strahlte zu mir, -\ndeinen besten Mut\nmachte er bangen!","translation":"A single glance from his flashing eye,\n- even through the lying figure\nshone brightly towards me, -\nyour best courage\nHe made me anxious!","literalText":true,"sourceStartIndex":21,"sourceLineCount":5},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Doch meinem Speere\nspart ihn sein Meineid?","translation":"But my spear\nDoes his perjury save him?","literalText":true,"sourceStartIndex":26,"sourceLineCount":2},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Eid und Meineid, müssige Acht!\nNach Stärkrem späh',\ndeinen Speer zu waffnen,\nwillst du den Stärksten bestehn!","translation":"Oaths and perjury, idle oaths!\nLook for strength,\nto arm your spear,\nDo you want to defeat the strongest?","literalText":true,"sourceStartIndex":28,"sourceLineCount":4},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Wohl kenn' ich Siegfrieds siegende Kraft,\nwie schwer im Kampf er zu fällen;\ndrum raune nun du mir klugen Rat,\nwie doch der Recke mir wich'?","translation":"I am well aware of Siegfried's victorious power,\nhow difficult it is to fell him in battle;\nTherefore, whisper to me now wise advice,\nHow the hero yielded to me!","literalText":true,"sourceStartIndex":32,"sourceLineCount":4},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"O Undank, schändlichster Lohn!\nNicht eine Kunst war mir bekannt,\ndie zum Heil nicht half seinem Leib'!\nUnwissend zähmt' ihn mein Zauberspiel,\ndas ihn vor Wunden nun gewahrt.","translation":"Oh, ingratitude, most shameful reward!\nI was not familiar with any art form,\nwhich did not help his body to save him!\nUnwittingly, my magic game tamed him,\nwhich now protects him from wounds.","literalText":true,"sourceStartIndex":36,"sourceLineCount":5},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"So kann keine Wehr ihm schaden?","translation":"So no defense can harm him?","literalText":true,"sourceStartIndex":41,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Im Kampfe nicht - ; doch\nträfst du im Rücken ihn....\nNiemals - das wusst ich -\nwich' er dem Feind,\nnie reicht' er fliehend ihm den Rücken:\nan ihm drum spart' ich den Segen.","translation":"Not in battle - ; but\nIf you hit him from behind...\nNever - I knew that -\nHe yielded to the enemy,\nHe never turns his back on him while fleeing:\nTherefore, I spared him the blessing.","literalText":true,"sourceStartIndex":42,"sourceLineCount":6},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Und dort trifft ihn mein Speer!","translation":"And there my spear strikes him!","literalText":true,"sourceStartIndex":48,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"er wendet sich rasch von Brünnhilde ab zu Gunther","translation":"He quickly turns away from Brünnhilde to Gunther.","literalText":true,"sourceStartIndex":49,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Auf, Gunther, edler Gibichung!\nHier steht dein starkes Weib:\nwas hängst du dort in Harm?","translation":"Up, Gunther, noble Gibichung!\nHere stands your strong woman:\nWhat are you hanging there in Harm?","literalText":true,"sourceStartIndex":50,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"leidenschaftlich auffahrend","translation":"passionately driving","literalText":true,"sourceStartIndex":53,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"O Schmach! O Schande!\nWehe mir, dem jammervollsten Manne!","translation":"Oh disgrace! Oh shame!\nWoe to me, the most wretched man!","literalText":true,"sourceStartIndex":54,"sourceLineCount":2},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"In Schande liegst du;\nleugn' ich das?","translation":"You are in shame;\nDo I deny that?","literalText":true,"sourceStartIndex":56,"sourceLineCount":2},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"zu Gunther","translation":"to Gunther","literalText":true,"sourceStartIndex":58,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"O feiger Mann! Falscher Genoss'!\nHinter dem Helden hehltest du dich,\ndass Preise des Ruhmes er dir erränge!\nTief wohl sank das teure Geschlecht,\ndas solche Zagen gezeugt!","translation":"O cowardly man! False comrade!\nYou hid behind the hero,\nMay he win prizes of glory for you!\nThe expensive sex may have sunk very low.\nthat such fears have been born!","literalText":true,"sourceStartIndex":59,"sourceLineCount":5},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"ausser sich","translation":"beside himself","literalText":true,"sourceStartIndex":64,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Betrüger ich - und betrogen!\nVerräter ich - und verraten!\nZermalmt mir das Mark!\nZerbrecht mir die Brust!\nHilf, Hagen! Hilf meiner Ehre!\nHilf deiner Mutter,\ndie mich - auch ja gebar!","translation":"I'm a cheater - and I'm the one who's been cheated!\nI am a traitor – and I am betrayed!\nCrush my marrow!\nBreak my chest!\nHelp, Hagen! Help my honor!\nHelp your mother,\nwho gave birth to me!","literalText":true,"sourceStartIndex":65,"sourceLineCount":7},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Dir hilft kein Hirn,\ndir hilft keine Hand:\ndir hilft nur - Siegfrieds Tod!","translation":"No brain can help you,\nNo hand can help you:\nThe only thing that can help you is Siegfried's death!","literalText":true,"sourceStartIndex":72,"sourceLineCount":3}]},{"type":"Passage","incipitOnly":true,"sourceTitlesOnly":true,"threeLineOutline":true,"originalTitle":"Siegfrieds Tod!","translatedTitle":"Siegfried's death!","participants":["GUNTHER","HAGEN","BRÜNNHILDE","GUNTHER UND BRÜNNHILDE"],"sourceStartIndex":75,"sourceLineCount":60,"turns":[{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"von Grausen erfasst","translation":"seized by horror","literalText":true,"sourceStartIndex":75,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Siegfrieds Tod!","translation":"Siegfried's death!","literalText":true,"sourceStartIndex":76,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Nur der sühnt deine Schmach!","translation":"Only he can atone for your shame!","literalText":true,"sourceStartIndex":77,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"vor sich hinstarrend","translation":"staring ahead","literalText":true,"sourceStartIndex":78,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Blutbrüderschaft schwuren wir uns!","translation":"We swore a swear of blood brotherhood!","literalText":true,"sourceStartIndex":79,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Des Bundes Bruch sühne nun Blut!","translation":"Now atone for the breach of the covenant with blood!","literalText":true,"sourceStartIndex":80,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Brach er den Bund?","translation":"Did he break the covenant?","literalText":true,"sourceStartIndex":81,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Da er dich verriet!","translation":"Because he betrayed you!","literalText":true,"sourceStartIndex":82,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Verriet er mich?","translation":"Did he betray me?","literalText":true,"sourceStartIndex":83,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Dich verriet er,\nund mich verrietet ihr alle!\nWär' ich gerecht, alles Blut der Welt\nbüsste mir nicht eure Schuld!\nDoch des einen Tod taugt mir für alle:\nSiegfried falle - zur Sühne für sich und euch!","translation":"He betrayed you,\nAnd you all betrayed me!\nIf I were just, all the blood in the world\nDon't make me pay for your debt!\nBut the death of one is good for all:\nSiegfried, fall – for atonement for himself and for you!","literalText":true,"sourceStartIndex":84,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"heimlich zu Gunther","translation":"secretly to Gunther","literalText":true,"sourceStartIndex":90,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Er falle - dir zum Heil!\nUngeheure Macht wird dir,\ngewinnst von ihm du den Ring,\nden der Tod ihm wohl nur entreisst.","translation":"May he fall – for your salvation!\nYou will be granted immense power,\nIf you win the ring from him,\nwhich death will likely only take from him.","literalText":true,"sourceStartIndex":91,"sourceLineCount":4},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"leise","translation":"quiet","literalText":true,"sourceStartIndex":95,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Brünnhildes Ring?","translation":"Brünnhilde's Ring?","literalText":true,"sourceStartIndex":96,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Des Nibelungen Reif.","translation":"The Nibelung's Hoop.","literalText":true,"sourceStartIndex":97,"sourceLineCount":1},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"schwer seufzend","translation":"heavy sigh","literalText":true,"sourceStartIndex":98,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"So wär' es Siegfrieds Ende!","translation":"That would be the end of Siegfried!","literalText":true,"sourceStartIndex":99,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Uns allen frommt sein Tod.","translation":"His death benefits us all.","literalText":true,"sourceStartIndex":100,"sourceLineCount":1},{"speaker":"GUNTHER","speakerTranslation":"GUNTHER","original":"Doch Gutrune, ach, der ich ihn gönnte!\nStraften den Gatten wir so,\nwie bestünden wir vor ihr?","translation":"But Gutrune, alas, I wish he were mine!\nDid we punish the husband like this?\nHow would we fare before her?","literalText":true,"sourceStartIndex":101,"sourceLineCount":3},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"wild auffahrend","translation":"Wildly driving","literalText":true,"sourceStartIndex":104,"sourceLineCount":1},{"speaker":"BRÜNNHILDE","speakerTranslation":"BRÜNNHILDE","original":"Was riet mir mein Wissen?\nWas wiesen mich Runen?\nIm hilflosen Elend achtet mir's hell:\nGutrune heisst der Zauber,\nder den Gatten mir entrückt!\nAngst treffe sie!","translation":"What advice did my knowledge give me?\nWhat did runes tell me?\nIn my helpless misery, I see brightly:\nThe spell is called Gutrune.\nwho takes my husband away from me!\nFear grips them!","literalText":true,"sourceStartIndex":105,"sourceLineCount":6},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"zu Gunther","translation":"to Gunther","literalText":true,"sourceStartIndex":111,"sourceLineCount":1},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Muss sein Tod sie betrüben,\nverhehlt sei ihr die Tat.\nAuf muntres Jagen ziehen wir morgen:\nder Edle braust uns voran,\nein Eber bracht' ihn da um.","translation":"Must his death grieve her?\nThe deed was concealed from her.\nWe're going on a lively hunt tomorrow:\nThe noble one rushes ahead of us,\nA boar killed him there.","literalText":true,"sourceStartIndex":112,"sourceLineCount":5},{"speaker":"GUNTHER UND BRÜNNHILDE","speakerTranslation":"GUNTHER UND BRÜNNHILDE","original":"So soll es sein! Siegfried falle!\nSühn' er die Schmach, die er mir schuf!\nDes Eides Treue hat er getrogen:\nmit seinem Blut büss' er die Schuld!\nAllrauner, rächender Gott!\nSchwurwissender Eideshort!\nWotan! Wende dich her!\nWeise die schrecklich heilige Schar,\nhieher zu horchen dem Racheschwur!","translation":"So be it! Siegfried fall!\nMay he atone for the disgrace he inflicted upon me!\nHe betrayed his oath of loyalty:\nHe will atone for his guilt with his blood!\nAll-ravishing, avenging God!\nOath-knowing oath shorthand!\nWotan! Turn here!\nWise the terribly holy host,\nListen here to the oath of revenge!","literalText":true,"sourceStartIndex":117,"sourceLineCount":9},{"speaker":"HAGEN","speakerTranslation":"HAGEN","original":"Sterb' er dahin, der strahlende Held!\nMein ist der Hort, mir muss er gehören.\nDrum sei der Reif ihm entrissen.\nAlben-Vater, gefallner Fürst!\nNachthüter! Niblungenherr!\nAlberich! Achte auf mich!\nWeise von neuem der Niblungen Schar,\ndir zu gehorchen, des Ringes Herrn!","translation":"Let him die, the shining hero!\nThe treasure is mine, it must belong to me.\nTherefore, the frost was torn from him.\nAlbum father, fallen prince!\nNight Watcher! Lord of the Nibelungs!\nAlberich! Watch out for me!\nWise anew of the Nibelung host\nTo obey you, Lord of the Ring!","literalText":true,"sourceStartIndex":126,"sourceLineCount":8},{"speaker":"Stage direction","speakerTranslation":"Stage direction","original":"Als Gunther mit Brünnhilde heftig der Halle sich zuwendet, tritt ihnen der von dort heraustretende Brautzug entgegen. Knaben und Mädchen, Blumenstäbe schwingend, springen lustig voraus. Siegfried wird auf einem Schilde, Gutrune auf einem Sessel von den Männern getragen. Auf der Anhöhe des Hintergrundes führen Knechte und Mägde auf verschiedenen Bergpfaden Opfergeräte und Opfertiere zu den Weihsteinen herbei und schmücken diese mit Blumen. Siegfried und die Mannen blasen auf ihren Hörnern den Hochzeitsruf. Die Frauen fordern Brünnhilde auf, an Gutrunes Seite sie zu geleiten. Brünnhilde blickt starr zu Gutrune auf, welche ihr mit freundlichem Lächeln zuwinkt. Als Brünnhilde heftig zurücktreten will, tritt Hagen rasch dazwischen und drängt sie an Gunther, der jetzt von neuem ihre Hand erfasst, worauf er selbst von den Männern sich auf den Schild heben lässt. Während der Zug, kaum unterbrochen, schnell der Höhe zu sich wieder in Bewegung setzt, fällt der Vorhang","translation":"As Gunther and Brünnhilde turn vehemently towards the hall, the bridal procession emerges from it. Boys and girls, waving flower-staffs, skip merrily ahead. Siegfried is carried on a shield, Gutrune on a chair by the men. On the hill in the background, servants and maids lead sacrificial implements and animals along various mountain paths to the votive stones and adorn them with flowers. Siegfried and the men sound the wedding call on their horns. The women urge Brünnhilde to escort them at Gutrune's side. Brünnhilde stares fixedly at Gutrune, who beckons to her with a friendly smile. When Brünnhilde tries to step back sharply, Hagen quickly intervenes and urges her towards Gunther, who now takes her hand again, whereupon he allows himself to be lifted onto the shield by the men. As the procession, barely interrupted, swiftly resumes its upward movement towards the hilltop, the curtain falls.","literalText":true,"sourceStartIndex":134,"sourceLineCount":1}]}]}];
